package main

import "testing"

func TestAdd(t *testing.T) {
	tests := []struct {
		name  string
		left  int
		right int
		want  int
	}{
		{name: "positive operands", left: 2, right: 3, want: 5},
		{name: "zeros", left: 0, right: 0, want: 0},
		{name: "negative operands", left: -2, right: -3, want: -5},
		{name: "mixed signs", left: -2, right: 3, want: 1},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := add(tt.left, tt.right); got != tt.want {
				t.Errorf("add(%d, %d) = %d, want %d", tt.left, tt.right, got, tt.want)
			}
		})
	}
}

